import sys

def main():
    lines = sys.stdin.read().splitlines()
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    n = len(s1)
    m = len(s2)
    v_len = len(virus)

    pi = [0] * v_len
    k = 0
    for i in range(1, v_len):
        while k > 0 and virus[i] != virus[k]:
            k = pi[k - 1]
        if virus[i] == virus[k]:
            k += 1
        pi[i] = k

    def get_next_state(state, char):
        while state > 0 and char != virus[state]:
            state = pi[state - 1]
        if char == virus[state]:
            state += 1
        return state

    dp = [[[-1] * v_len for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for state in range(v_len):
                if dp[i][j][state] == -1:
                    continue
                current_len = dp[i][j][state]

                if i < n and j < m and s1[i] == s2[j]:
                    char = s1[i]
                    next_state = get_next_state(state, char)
                    if next_state < v_len:
                        if dp[i + 1][j + 1][next_state] < current_len + 1:
                            dp[i + 1][j + 1][next_state] = current_len + 1

                if i < n:
                    if dp[i + 1][j][state] < current_len:
                        dp[i + 1][j][state] = current_len

                if j < m:
                    if dp[i][j + 1][state] < current_len:
                        dp[i][j + 1][state] = current_len

    max_len = 0
    best_state = 0
    for state in range(v_len):
        if dp[n][m][state] > max_len:
            max_len = dp[n][m][state]
            best_state = state

    if max_len == 0:
        print(0)
        return

    result = []
    i, j, state = n, m, best_state
    while i > 0 or j > 0:
        if i > 0 and j > 0 and s1[i - 1] == s2[j - 1]:
            char = s1[i - 1]
            prev_state = -1
            for s in range(v_len):
                if get_next_state(s, char) == state:
                    if dp[i - 1][j - 1][s] == dp[i][j][state] - 1:
                        prev_state = s
                        break
            if prev_state != -1:
                result.append(char)
                i -= 1
                j -= 1
                state = prev_state
                continue

        found = False
        if i > 0 and dp[i - 1][j][state] == dp[i][j][state]:
            i -= 1
            found = True
        elif j > 0 and dp[i][j - 1][state] == dp[i][j][state]:
            j -= 1
            found = True

        if not found:
            break

    print("".join(reversed(result)))

if __name__ == "__main__":
    main()
